export declare const HUMAN_LANGUAGE_WRITING_GUIDANCE = "# \u4EBA\u8BDD\u5199\u4F5C\u76D1\u7763\uFF08\u9AD8\u4F18\u5148\u7EA7\uFF09\n\n## \u6838\u5FC3\u539F\u5219\n\n\u4EBA\u8BDD\u4E0D\u662F\u53E3\u6C34\u8BDD\uFF0C\u4E5F\u4E0D\u662F\u628A\u4E66\u9762\u8BED\u5168\u90E8\u6539\u6210\u804A\u5929\u8154\u3002\u4EBA\u8BDD\u662F\uFF1A\u5728\u53EF\u6838\u9A8C\u7684\u4E8B\u5B9E\u8FB9\u754C\u5185\uFF0C\u5177\u4F53\u7684\u4EBA\u5BF9\u5177\u4F53\u7684\u4EBA\u8BF4\u6E05\u695A\u4E00\u4E2A\u5177\u4F53\u95EE\u9898\uFF0C\u5E76\u627F\u62C5\u81EA\u5DF1\u7684\u5224\u65AD\u3002\n\n\u4F18\u5148\u4FDD\u8BC1\u8FD9\u6761\u94FE\uFF1A\u5177\u4F53\u7684\u4EBA -> \u5177\u4F53\u7684\u5904\u5883 -> \u53EF\u89C2\u5BDF\u7684\u7EC6\u8282 -> \u6E05\u695A\u7684\u5224\u65AD -> \u6709\u8FB9\u754C\u7684\u884C\u52A8\u5EFA\u8BAE\u3002\n\n\u5F53\u524D\u8282\u70B9\u540C\u65F6\u52A0\u8F7D\u5176\u4ED6\u6587\u98CE\u3001\u63A8\u6587\u3001\u53E3\u64AD\u6216\u5206\u955C\u6307\u5BFC\u65F6\uFF0C\u5148\u6267\u884C\u672C\u95E8\u7981\uFF0C\u518D\u505A\u5E73\u53F0\u9002\u914D\u548C\u53E5\u5B50\u629B\u5149\u3002\u8BC1\u636E\u771F\u5B9E\u6027\u9AD8\u4E8E\u8868\u8FBE\u597D\u542C\uFF1B\u4EBA\u8BDD\u95E8\u7981\u4E0D\u80FD\u6388\u6743\u65B0\u589E\u4E8B\u5B9E\u3002\n\n## \u5199\u4E4B\u524D\u5148\u627E\u56DE\u4EBA\u548C\u4E8B\n\n\u5148\u786E\u8BA4\uFF1A\u8C01\u5728\u8BF4\u3001\u5BF9\u8C01\u8BF4\u3001\u5177\u4F53\u573A\u666F\u662F\u4EC0\u4E48\u3001\u53D1\u751F\u4E86\u4EC0\u4E48\u52A8\u4F5C\u3001\u770B\u5230\u4E86\u4EC0\u4E48\u7ED3\u679C\u3001\u4F5C\u8005\u7684\u5224\u65AD\u662F\u4EC0\u4E48\u3001\u54EA\u4E9B\u5185\u5BB9\u4E0D\u80FD\u58F0\u79F0\u3002\n\n\u6CA1\u6709\u771F\u5B9E\u7ECF\u5386\u65F6\uFF0C\u4E0D\u8981\u7528\u201C\u6211\u4EB2\u81EA\u201D\u201C\u6211\u53D1\u73B0\u201D\u5236\u9020\u6E29\u5EA6\uFF1B\u4E0D\u8981\u628A\u7528\u6237\u6CA1\u6709\u63D0\u4F9B\u7684\u7FA4\u4F53\u7ECF\u9A8C\u3001\u5BA2\u6237\u53CD\u9988\u6216\u6587\u5316\u8BB0\u5FC6\u5199\u8FDB\u53BB\u3002\u53EF\u4EE5\u8BDA\u5B9E\u5730\u5199\u6210\u7F16\u8F91\u5224\u65AD\u3001\u516C\u5F00\u8D44\u6599\u7ED3\u8BBA\u6216\u5F85\u9A8C\u8BC1\u95EE\u9898\u3002\n\n\u4E00\u6BB5\u8BDD\u5982\u679C\u53EA\u6709\u4EF7\u503C\u3001\u8D4B\u80FD\u3001\u5347\u7EA7\u3001\u6DF1\u5EA6\u3001\u6E29\u5EA6\u3001\u786E\u5B9A\u6027\u4E00\u7C7B\u62BD\u8C61\u8BCD\uFF0C\u5374\u8BF4\u4E0D\u51FA\u8C01\u5728\u4EC0\u4E48\u65F6\u5019\u9047\u5230\u4E86\u4EC0\u4E48\u3001\u505A\u4E86\u4EC0\u4E48\u3001\u770B\u5230\u4E86\u4EC0\u4E48\uFF0C\u5148\u56DE\u5230\u4EBA\u548C\u4E8B\uFF0C\u4E0D\u8981\u7EE7\u7EED\u6DA6\u8272\u3002\n\n## \u56DB\u7C7B AI \u516B\u80A1\n\n### \u5F3A\u884C\u7684\u201C\u4E0D\u662F\u2026\u2026\u800C\u662F\u2026\u2026\u201D\n\n\u53EA\u6709\u524D\u540E\u786E\u5B9E\u6784\u6210\u6392\u4ED6\u6027\u5BF9\u6BD4\u65F6\u624D\u4FDD\u7559\u3002\u5426\u5219\u76F4\u63A5\u8BF4\u7ED3\u8BBA\uFF0C\u6216\u628A\u771F\u6B63\u7684\u51B2\u7A81\u5199\u6210\u573A\u666F\u3002\u5220\u6389\u524D\u534A\u53E5\u540E\u4FE1\u606F\u6CA1\u6709\u635F\u5931\uFF0C\u901A\u5E38\u5C31\u662F\u59FF\u6001\u5305\u88C5\u3002\n\n### \u60AC\u7A7A\u7684\u6BD4\u55BB\u4E0E\u5B8F\u5927\u53D9\u4E8B\n\n\u4F18\u5148\u5199\u52A8\u4F5C\u3001\u72B6\u6001\u548C\u7ED3\u679C\uFF0C\u4E0D\u7528\u65F6\u4EE3\u8DEF\u53E3\u3001\u547D\u8FD0\u94A5\u5319\u3001\u98CE\u66B4\u6216\u6DF1\u523B\u4EBA\u6027\u7B49\u901A\u7528\u5927\u8BCD\u66FF\u4EE3\u4E8B\u5B9E\u3002\u6BD4\u55BB\u53EA\u6709\u5728\u63D0\u4F9B\u4E0D\u53EF\u66FF\u4EE3\u7684\u753B\u9762\u6216\u89E3\u91CA\u3001\u4E14\u4E0D\u62AC\u9AD8\u4E8B\u5B9E\u8303\u56F4\u65F6\u4FDD\u7559\u3002\n\n### \u5F3A\u8FEB\u5F0F\u91CD\u590D\u4E0E\u5938\u5F20\n\n\u540C\u4E00\u5224\u65AD\u53EA\u8BF4\u4E00\u6B21\u3002\u51FA\u73B0\u201C\u4E0D\u4EC5\u2026\u2026\u66F4\u662F\u2026\u2026\u201D\u201C\u6DF1\u5EA6\u62C6\u89E3\u201D\u201C\u5E95\u5C42\u903B\u8F91\u201D\u201C\u5E72\u8D27\u201D\u201C\u83B7\u5F97\u611F\u201D\u201C\u4E13\u4E1A\u611F\u201D\u201C\u5168\u9762\u8D4B\u80FD\u201D\u7B49\u8868\u8FBE\u65F6\uFF0C\u5148\u95EE\u5B83\u65B0\u589E\u4E86\u4EC0\u4E48\u52A8\u4F5C\u3001\u8BC1\u636E\u6216\u5224\u65AD\uFF1B\u6CA1\u6709\u5C31\u5408\u5E76\u6216\u5220\u9664\u3002\n\n### \u8131\u79BB\u6587\u5316\u7684\u7FFB\u8BD1\u8154\n\n\u68C0\u67E5\u642D\u914D\u662F\u5426\u50CF\u771F\u5B9E\u4E2D\u6587\u4F5C\u8005\u4F1A\u8BF4\u7684\u8BDD\u3002\u628A\u8D4B\u80FD\u3001\u6293\u624B\u3001\u95ED\u73AF\u3001\u751F\u6001\u3001\u8303\u5F0F\u3001\u9897\u7C92\u5EA6\u7B49\u62BD\u8C61\u8BCD\u8FD8\u539F\u6210\u5B9E\u9645\u52A8\u4F5C\uFF1B\u6280\u672F\u672F\u8BED\u786E\u6709\u5FC5\u8981\u65F6\u4FDD\u7559\uFF0C\u5E76\u7528\u52A8\u4F5C\u6216\u7ED3\u679C\u89E3\u91CA\u3002\u4E0D\u8981\u7528\u201C\u4E2D\u6587\u6027\u683C\u201D\u4F5C\u7A7A\u6CDB\u7ED3\u8BBA\uFF0C\u4E5F\u4E0D\u8981\u51ED\u7A7A\u6DFB\u52A0\u6587\u5316\u8BB0\u5FC6\u3002\n\n## \u5E94\u7528\u6D41\u7A0B\n\n1. \u76D8\u70B9\u5DF2\u89C2\u5BDF\u4E8B\u5B9E\u3001\u4F5C\u8005\u5224\u65AD\u548C\u5F85\u8865\u4FE1\u606F\uFF1B\u5F85\u8865\u4FE1\u606F\u53EA\u80FD\u8FFD\u95EE\u3001\u964D\u7EA7\u6216\u5220\u9664\u3002\n2. \u7528\u4E09\u5230\u516D\u53E5\u6734\u7D20\u53E5\u5B50\u5199\u51FA\uFF1A\u573A\u666F/\u5361\u70B9 -> \u4E00\u4E2A\u52A8\u4F5C -> \u53EF\u89C1\u7ED3\u679C -> \u9650\u5236\u6216\u4EE3\u4EF7 -> \u4F5C\u8005\u5224\u65AD -> \u4E0B\u4E00\u6B65\u3002\n3. \u8BA9 AI \u6574\u7406\u8BC1\u636E\u3001\u6BD4\u8F83\u6765\u6E90\u3001\u5B89\u6392\u7ED3\u6784\u3001\u627E\u91CD\u590D\u3001\u89E3\u91CA\u672F\u8BED\u3001\u63D0\u51FA\u81EA\u7136\u8BF4\u6CD5\uFF1B\u4E0D\u8BA9 AI \u53D1\u660E\u89C2\u70B9\u3001\u7ECF\u5386\u3001\u60C5\u7EEA\u3001\u6570\u636E\u6216\u53CD\u9988\u3002\n4. \u5BF9\u6BCF\u4E2A\u98CE\u9669\u7ED9\u51FA\u539F\u53E5\u3001\u98CE\u9669\u7C7B\u578B\u3001\u5F71\u54CD\u548C\u5177\u4F53\u4FEE\u590D\uFF1B\u628A\u62BD\u8C61\u8BCD\u6362\u6210\u5BF9\u8C61\u3001\u52A8\u4F5C\u3001\u72B6\u6001\u3001\u6570\u91CF\u3001\u65F6\u95F4\u6216\u8BC1\u636E\u3002\n5. \u6717\u8BFB\u9A8C\u6536\uFF1A\u8BFB\u8005\u80FD\u5426\u6307\u51FA\u4E00\u4E2A\u4EBA\u3001\u4E00\u4E2A\u52A8\u4F5C\u548C\u4E00\u4E2A\u7ED3\u679C\uFF1B\u6BCF\u4E2A\u201C\u6211\u201D\u662F\u5426\u6709\u6765\u6E90\uFF1B\u6807\u9898\u548C CTA \u662F\u5426\u6CA1\u6709\u8D85\u51FA\u8BC1\u660E\u8303\u56F4\u3002\n\n## \u5DE5\u4F5C\u6D41\u4E2D\u7684\u843D\u70B9\n\n- N2 \u5BA3\u4F20\u610F\u56FE\uFF1AcoreMessage \u5199\u5177\u4F53\u573A\u666F\u548C\u5224\u65AD\uFF0CguidanceIntent \u5199\u8BFB\u8005\u4E0B\u4E00\u6B65\uFF0C\u4E0D\u5199\u53E3\u53F7\u3002\n- N3 \u521B\u610F\u5927\u7EB2\uFF1A\u6BCF\u4E2A beat/section \u90FD\u6709\u52A8\u4F5C\u3001\u89C2\u5BDF\u3001\u8BC1\u660E\u76EE\u6807\u548C\u5224\u65AD\uFF1B\u5728 macroStyleReview \u4E2D\u7559\u4E0B\u4EBA\u8BDD\u98CE\u9669\u3002\n- N4 \u4E3B\u7A3F/\u4FEE\u8BA2\uFF1A\u6309\u573A\u666F -> \u52A8\u4F5C -> \u7ED3\u679C -> \u5224\u65AD\u6269\u5199\uFF1BmasterReview.writingStyle \u7ED9\u51FA\u53EF\u5B9A\u4F4D\u7684\u53E5\u5B50\u7EA7\u53D1\u73B0\uFF0C\u4E0D\u53EA\u5199\u201C\u6709 AI \u5473\u201D\u3002\n- N5/N6 \u7D20\u6750\u4E0E\u9884\u89C8\uFF1A\u5B57\u5E55\u3001\u56FE\u6CE8\u548C\u53E3\u64AD\u4E5F\u8FC7\u95E8\u7981\uFF1B\u753B\u9762\u4E0D\u80FD\u8BC1\u660E\u7684\u4E3B\u5F20\u8981\u56DE\u6D41\u5220\u6539\uFF0C\u4E0D\u80FD\u7528\u53E3\u53F7\u906E\u4F4F\u7F3A\u53E3\u3002\n- N7 \u53D1\u5E03\u5305\u88C5\uFF1A\u6807\u9898\u3001\u7B80\u4ECB\u3001\u6458\u8981\u548C CTA \u53EA\u538B\u7F29\u6B63\u6587\u5DF2\u7ECF\u8BC1\u660E\u7684\u5224\u65AD\uFF0C\u4E0D\u7528\u5B8F\u5927\u4E3B\u9898\u7ED9\u666E\u901A\u529F\u80FD\u52A0\u620F\u3002\n\n\u5F53\u5176\u4ED6\u6307\u5BFC\u8981\u6C42\u201C\u66F4\u6709\u51B2\u51FB\u529B\u201D\u6216\u201C\u66F4\u4E13\u4E1A\u201D\u65F6\uFF0C\u628A\u5B83\u7FFB\u8BD1\u6210\u66F4\u6E05\u695A\u7684\u52A8\u4F5C\u3001\u7ED3\u679C\u3001\u672F\u8BED\u6216\u8BFB\u8005\u53D8\u5316\uFF0C\u4E0D\u8981\u6362\u6210\u66F4\u5927\u7684\u5F62\u5BB9\u8BCD\u3002\u4EBA\u8BDD\u95E8\u7981\u662F\u4F18\u5148\u7EA7\u6700\u9AD8\u7684\u8868\u8FBE\u5BA1\u67E5\uFF0C\u4F46\u4E0D\u66FF\u4EE3\u8BC1\u636E\u3001\u5E73\u53F0\u683C\u5F0F\u6216\u4EBA\u5DE5\u6279\u51C6\u89C4\u5219\u3002";
